//! Generate the read-op ConnectRPC surface from `shipd::services::schema::OPS`.
//!
//! Every read op (permission `*.read`) with no required args becomes a
//! `ReadOpsService` proto method + a `shipd` dispatch arm — the bulk port,
//! projected from the registry. The hand-written `account.state` locked the
//! target shape; this replaces the 50× repetition. Arg-bearing reads are a
//! later pass (they need typed request fields). Run: `cargo xtask gen-ops`.
//!
//! Outputs (committed, `@generated` — do not hand-edit):
//!   - `proto/ship/ops/v1/reads.gen.proto`     (ReadOpsService + request msgs)
//!   - `apps/shipd/src/ops_reads_gen.rs`       (`impl ReadOpsService for OpsImpl`)

use std::fmt::Write as _;
use std::path::PathBuf;

use anyhow::{Context, Result};

/// Read return-types that have a hand-authored proto message (named identically
/// to the Rust wire struct) in `proto/ship/ops/v1/types.proto`. A read whose
/// `OpDescriptor.returns` is listed here gets a typed Connect return
/// (`returns (<Type>)` + a `from_value` decode); every other read stays on the
/// `JsonResponse` blob. Grows as wire structs are mirrored into proto, one
/// service at a time — the read half of the typed contract.
const TYPED_READS: &[&str] = &[
    // rules
    "RulesIndexResponse",
    "RuleGetResponse",
    // mcp / permissions — list + tool_patterns (the *.get reads carry an
    // embedded opaque config Value, so they stay JsonResponse).
    "McpIndexResponse",
    "PermissionsIndexResponse",
    "ToolPatternsResponse",
    // list/index + scalar reads reusing already-typed leaves
    "SkillsIndexResponse",
    "PipelinesIndexResponse",
    "SkillFileResponse",
    "WorkspaceActiveResponse",
    "ArtifactsListResponse",
    // git — all fully structured
    "GitLogResponse",
    "GitBranchesResponse",
    "GitOverviewResponse",
    "GitDiffResponse",
    "StatusBuckets",
    // sessions / chat / events / specs / actors / agents index
    "SessionsListResponse",
    "ChatStateResponse",
    "EventsListResponse",
    "SpecsListResponse",
    "SpecGetResponse",
    "ActorsListResponse",
    "AgentIndexResponse",
    // agent catalogs + summaries
    "AgentTemplatesResponse",
    "PermissionPresetsResponse",
    "HarnessesResponse",
    "AgentsSummariesResponse",
];

struct ReadOp {
    /// Registry op name, e.g. `account.state`.
    op: String,
    /// Proto method name, e.g. `AccountState`.
    method: String,
    /// Generated trait method (connectrpc snake-cases the proto name).
    snake: String,
    /// Required capability string (the op's `permission`).
    capability: String,
    /// Request parameters (empty for no-arg reads).
    args: Vec<Arg>,
    /// Proto response message name when typed (in `TYPED_READS`); else empty
    /// (the read returns `JsonResponse`).
    response_type: String,
}

struct Arg {
    name: String,
    /// Proto scalar type for the request field.
    proto_type: &'static str,
    /// String-valued (vs numeric) — drives the arg-building + the unset check.
    is_string: bool,
    required: bool,
}

/// PascalCase a dotted/underscored op name: `agents.permission_presets`
/// → `AgentsPermissionPresets`.
fn pascal(op: &str) -> String {
    op.split(['.', '_'])
        .map(|seg| {
            let mut chars = seg.chars();
            match chars.next() {
                Some(first) => first.to_uppercase().chain(chars).collect::<String>(),
                None => String::new(),
            }
        })
        .collect()
}

fn collect() -> Vec<ReadOp> {
    let mut out = Vec::new();
    for op in shipd::services::schema::OPS.iter() {
        if !op.permission.ends_with(".read") {
            continue; // commands get typed messages, not the JSON bridge
        }
        let args = op
            .args
            .iter()
            .map(|a| {
                let is_string = !a.kind.starts_with("number");
                Arg {
                    name: a.name.to_string(),
                    proto_type: if is_string { "string" } else { "int64" },
                    is_string,
                    required: a.required,
                }
            })
            .collect();
        let response_type = if TYPED_READS.contains(&op.returns) {
            op.returns.to_string()
        } else {
            String::new()
        };
        out.push(ReadOp {
            op: op.name.to_string(),
            method: pascal(op.name),
            snake: op.name.replace('.', "_"),
            capability: op.permission.to_string(),
            args,
            response_type,
        });
    }
    out
}

fn render_proto(ops: &[ReadOp]) -> String {
    let mut s = String::new();
    s.push_str(
        "// @generated by `cargo xtask gen-ops` from shipd::services::schema::OPS.\n\
         // Do not hand-edit — re-run the generator. Read ops projected onto Connect:\n\
         // each carries its proto policy options; the body is the registry JSON\n\
         // (JsonResponse), the impl delegates to services::registry::call.\n\
         syntax = \"proto3\";\n\n\
         package ship.ops.v1;\n\n\
         import \"ship/ops/v1/policy.proto\";\n\
         import \"ship/ops/v1/ops.proto\";\n\
         import \"ship/ops/v1/types.proto\";\n\n\
         service ReadOpsService {\n",
    );
    for o in ops {
        let ret = if o.response_type.is_empty() { "JsonResponse" } else { &o.response_type };
        let _ = write!(
            s,
            "  rpc {m}({m}Request) returns ({ret}) {{\n    \
             option (ship.ops.v1.capability) = \"{cap}\";\n    \
             option (ship.ops.v1.blast_radius) = BLAST_RADIUS_C0_SAFE;\n  }}\n",
            m = o.method,
            ret = ret,
            cap = o.capability,
        );
    }
    s.push_str("}\n");
    for o in ops {
        let _ = write!(s, "\nmessage {m}Request {{\n", m = o.method);
        for (i, arg) in o.args.iter().enumerate() {
            let _ = write!(
                s,
                "  {ty} {name} = {n};\n",
                ty = arg.proto_type,
                name = arg.name,
                n = i + 1
            );
        }
        s.push_str("}\n");
    }
    s
}

fn render_rust(ops: &[ReadOp]) -> String {
    let mut s = String::new();
    s.push_str(
        "// @generated by `cargo xtask gen-ops` from shipd::services::schema::OPS.\n\
         // Do not hand-edit. Included from ops_rpc.rs; OpsImpl + dispatch_json are\n\
         // in scope there. Each read op delegates to the registry via dispatch_json.\n\
         #[allow(refining_impl_trait)]\n\
         impl ::ship_ops_rpc::ReadOpsService for OpsImpl {\n",
    );
    for o in ops {
        let req_binding = if o.args.is_empty() { "_req" } else { "req" };
        let ret_ty = if o.response_type.is_empty() {
            "::ship_ops_rpc::JsonResponse".to_string()
        } else {
            format!("::ship_ops_rpc::{}", o.response_type)
        };
        let _ = write!(
            s,
            "    async fn {snake}(\n        &self,\n        \
             _ctx: ::connectrpc::RequestContext,\n        \
             {req}: ::ship_ops_rpc::Owned{m}RequestView,\n    ) -> \
             ::connectrpc::ServiceResult<{ret_ty}> {{\n",
            snake = o.snake,
            m = o.method,
            req = req_binding,
            ret_ty = ret_ty,
        );
        // No-arg reads pass Null; typed reads decode onto their proto message.
        if o.args.is_empty() {
            let call = if o.response_type.is_empty() {
                format!("        self.dispatch_json(\"{op}\")\n    }}\n", op = o.op)
            } else {
                format!(
                    "        self.dispatch_typed::<{ret_ty}>(\"{op}\", ::serde_json::Value::Null)\n    }}\n",
                    ret_ty = ret_ty,
                    op = o.op,
                )
            };
            s.push_str(&call);
            continue;
        }
        s.push_str("        let mut args = ::serde_json::Map::new();\n");
        for arg in &o.args {
            let insert = format!(
                "args.insert(\"{n}\".to_string(), ::serde_json::json!(req.{n}));",
                n = arg.name
            );
            if arg.required {
                let _ = write!(s, "        {insert}\n");
            } else if arg.is_string {
                let _ = write!(s, "        if !req.{n}.is_empty() {{ {insert} }}\n", n = arg.name);
            } else {
                let _ = write!(s, "        if req.{n} != 0 {{ {insert} }}\n", n = arg.name);
            }
        }
        let call = if o.response_type.is_empty() {
            format!(
                "        self.dispatch_json_args(\"{op}\", ::serde_json::Value::Object(args))\n    }}\n",
                op = o.op,
            )
        } else {
            format!(
                "        self.dispatch_typed::<{ret_ty}>(\"{op}\", ::serde_json::Value::Object(args))\n    }}\n",
                ret_ty = ret_ty,
                op = o.op,
            )
        };
        s.push_str(&call);
    }
    s.push_str("}\n");
    s
}

// ── Commands (write surface) ─────────────────────────────────────────────
// Projected from `schema::COMMANDS` onto `CommandOpsService`. Each method builds
// its args from the typed request and delegates to `services::command::call`.

#[derive(Clone, Copy)]
enum CmdArgKind {
    Str,
    Num,
    Bool,
    StrArray,
    Map,
}

struct CmdArg {
    name: String,
    kind: CmdArgKind,
}

struct CommandOp {
    op: String,
    method: String,
    snake: String,
    capability: String,
    blast: String,
    args: Vec<CmdArg>,
    /// Typed proto response message (from `CommandDescriptor.response_type`).
    /// Empty = the legacy `JsonResponse` blob.
    response_type: String,
}

fn cmd_arg_kind(kind: &str) -> CmdArgKind {
    if kind.starts_with("number") {
        CmdArgKind::Num
    } else if kind.starts_with("bool") {
        CmdArgKind::Bool
    } else if kind == "string[]" {
        CmdArgKind::StrArray
    } else if kind == "map" {
        CmdArgKind::Map
    } else {
        CmdArgKind::Str
    }
}

fn collect_commands() -> Vec<CommandOp> {
    shipd::services::schema::COMMANDS
        .iter()
        .map(|c| CommandOp {
            op: c.name.to_string(),
            method: pascal(c.name),
            snake: c.name.replace('.', "_"),
            capability: c.permission.to_string(),
            blast: c.blast_radius.to_string(),
            args: c
                .args
                .iter()
                .map(|a| CmdArg { name: a.name.to_string(), kind: cmd_arg_kind(a.kind) })
                .collect(),
            response_type: c.response_type.to_string(),
        })
        .collect()
}

fn cmd_proto_field(arg: &CmdArg, n: usize) -> String {
    let ty = match arg.kind {
        CmdArgKind::Str => format!("string {}", arg.name),
        CmdArgKind::Num => format!("int64 {}", arg.name),
        CmdArgKind::Bool => format!("optional bool {}", arg.name),
        CmdArgKind::StrArray => format!("repeated string {}", arg.name),
        CmdArgKind::Map => format!("map<string, string> {}", arg.name),
    };
    format!("  {ty} = {n};\n")
}

fn render_commands_proto(ops: &[CommandOp]) -> String {
    let mut s = String::new();
    s.push_str(
        "// @generated by `cargo xtask gen-ops` from shipd::services::schema::COMMANDS.\n\
         // Do not hand-edit — re-run the generator. Command (mutation) surface on\n\
         // Connect: each rpc carries its proto policy; the impl delegates to\n\
         // services::command::call (one write path, all transports thin).\n\
         syntax = \"proto3\";\n\n\
         package ship.ops.v1;\n\n\
         import \"ship/ops/v1/policy.proto\";\n\
         import \"ship/ops/v1/ops.proto\";\n\
         import \"ship/ops/v1/types.proto\";\n\n\
         service CommandOpsService {\n",
    );
    for o in ops {
        let ret = if o.response_type.is_empty() { "JsonResponse" } else { &o.response_type };
        let _ = write!(
            s,
            "  rpc {m}({m}Request) returns ({ret}) {{\n    \
             option (ship.ops.v1.capability) = \"{cap}\";\n    \
             option (ship.ops.v1.blast_radius) = BLAST_RADIUS_{blast};\n  }}\n",
            m = o.method,
            ret = ret,
            cap = o.capability,
            blast = o.blast,
        );
    }
    s.push_str("}\n");
    for o in ops {
        let _ = write!(s, "\nmessage {m}Request {{\n", m = o.method);
        for (i, arg) in o.args.iter().enumerate() {
            s.push_str(&cmd_proto_field(arg, i + 1));
        }
        s.push_str("}\n");
    }
    s
}

fn cmd_build_arg(arg: &CmdArg) -> String {
    let n = &arg.name;
    match arg.kind {
        CmdArgKind::Str | CmdArgKind::Num => format!(
            "        args.insert(\"{n}\".to_string(), ::serde_json::json!(req.{n}));\n"
        ),
        CmdArgKind::Bool => format!(
            "        if let Some(b) = req.{n} {{ args.insert(\"{n}\".to_string(), ::serde_json::json!(b)); }}\n"
        ),
        CmdArgKind::StrArray => format!(
            "        args.insert(\"{n}\".to_string(), ::serde_json::json!(req.{n}.iter().collect::<::std::vec::Vec<_>>()));\n"
        ),
        CmdArgKind::Map => format!(
            "        {{ let mut m = ::serde_json::Map::new(); for (k, v) in req.{n}.iter() {{ m.insert(k.to_string(), ::serde_json::json!(v)); }} args.insert(\"{n}\".to_string(), ::serde_json::Value::Object(m)); }}\n"
        ),
    }
}

fn render_commands_rust(ops: &[CommandOp]) -> String {
    let mut s = String::new();
    s.push_str(
        "// @generated by `cargo xtask gen-ops` from shipd::services::schema::COMMANDS.\n\
         // Do not hand-edit. Included from ops_rpc.rs; OpsImpl is in scope. Each\n\
         // command builds args from the typed request + calls services::command::call.\n\
         #[allow(refining_impl_trait)]\n\
         impl ::ship_ops_rpc::CommandOpsService for OpsImpl {\n",
    );
    for o in ops {
        let ret = if o.response_type.is_empty() {
            "::ship_ops_rpc::JsonResponse".to_string()
        } else {
            format!("::ship_ops_rpc::{}", o.response_type)
        };
        let _ = write!(
            s,
            "    async fn {snake}(\n        &self,\n        \
             ctx: ::connectrpc::RequestContext,\n        \
             req: ::ship_ops_rpc::Owned{m}RequestView,\n    ) -> \
             ::connectrpc::ServiceResult<{ret}> {{\n",
            snake = o.snake,
            m = o.method,
            ret = ret,
        );
        s.push_str(
            "        let auth = ctx.extensions.get::<crate::auth::AuthContext>().ok_or_else(|| ::connectrpc::ConnectError::unauthenticated(\"auth context required\"))?;\n",
        );
        s.push_str("        let mut args = ::serde_json::Map::new();\n");
        for arg in &o.args {
            s.push_str(&cmd_build_arg(arg));
        }
        // The Ok arm: typed ops decode the command's JSON value onto their proto
        // message (buffa serde, snake-alias + unknown-field tolerant); untyped
        // ops carry the raw JSON in a `JsonResponse` blob.
        let ok_arm = if o.response_type.is_empty() {
            "Ok(value) => Ok(::connectrpc::Response::new(::ship_ops_rpc::JsonResponse { json: value.to_string(), ..Default::default() })),".to_string()
        } else {
            format!(
                "Ok(value) => {{\n                let msg = ::serde_json::from_value::<{ret}>(value).map_err(|e| ::connectrpc::ConnectError::internal(format!(\"decode {op} response: {{e}}\")))?;\n                Ok(::connectrpc::Response::new(msg))\n            }}",
                ret = ret,
                op = o.op,
            )
        };
        let _ = write!(
            s,
            "        let cmd_ctx = crate::services::command::CommandCtx {{ state: &self.state, auth }};\n        \
             match crate::services::command::call(\"{op}\", &::serde_json::Value::Object(args), &cmd_ctx).await {{\n            \
             {ok_arm}\n            \
             Err(e) => Err(crate::ops_rpc::command_error_to_connect(e)),\n        }}\n    }}\n",
            op = o.op,
            ok_arm = ok_arm,
        );
    }
    s.push_str("}\n");
    s
}

pub fn run() -> Result<()> {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");
    let ops = collect();

    let proto_path = root.join("proto/ship/ops/v1/reads.gen.proto");
    std::fs::write(&proto_path, render_proto(&ops))
        .with_context(|| format!("writing {}", proto_path.display()))?;

    let rust_path = root.join("apps/shipd/src/ops_reads_gen.rs");
    std::fs::write(&rust_path, render_rust(&ops))
        .with_context(|| format!("writing {}", rust_path.display()))?;

    let commands = collect_commands();
    let cmd_proto = root.join("proto/ship/ops/v1/commands.gen.proto");
    std::fs::write(&cmd_proto, render_commands_proto(&commands))
        .with_context(|| format!("writing {}", cmd_proto.display()))?;

    let cmd_rust = root.join("apps/shipd/src/ops_commands_gen.rs");
    std::fs::write(&cmd_rust, render_commands_rust(&commands))
        .with_context(|| format!("writing {}", cmd_rust.display()))?;

    eprintln!(
        "gen-ops: {} read ops + {} commands → reads.gen.proto/ops_reads_gen.rs + commands.gen.proto/ops_commands_gen.rs",
        ops.len(),
        commands.len(),
    );
    Ok(())
}
